-- Installed-contract verifier; catalog-only and rollback-safe.
\set ON_ERROR_STOP on
begin;
create temporary table m117_expected(signature text primary key,definition_md5 text,owner_name text,acl jsonb) on commit drop;
do $$ declare problems text;begin
 select string_agg(e.signature,', ' order by e.signature) into problems
 from m117_expected e left join pg_proc p on p.oid=to_regprocedure('public.'||e.signature)
 where p.oid is null or md5(pg_get_functiondef(p.oid))<>e.definition_md5 or pg_get_userbyid(p.proowner)<>e.owner_name
 or (select jsonb_agg(a::text order by a::text) from unnest(p.proacl) a) is distinct from e.acl;
 if problems is not null then raise exception '117 function definition/owner/grant mismatch: %',problems;end if;
 if (select count(*) from pg_proc where pronamespace='public'::regnamespace)<>(select count(*) from m117_expected) then raise exception 'Unexpected application function';end if;
 if (select count(*) from information_schema.columns where table_schema='public' and table_name in ('study_deck_node_preferences','study_deck_personal_topic_preferences') and column_name='reset_source' and udt_name='uuid' and is_nullable='YES')<>2 then raise exception 'Reset-source metadata mismatch';end if;
 if not (select bool_and(relrowsecurity) from pg_class where oid in('public.study_deck_node_preferences'::regclass,'public.study_deck_personal_topic_preferences'::regclass)) then raise exception 'Preference RLS disabled';end if;
 if has_table_privilege('authenticated','public.study_deck_node_preferences','INSERT,UPDATE,DELETE') or has_table_privilege('authenticated','public.study_deck_personal_topic_preferences','INSERT,UPDATE,DELETE')
 or has_function_privilege('authenticated','public.set_study_deck_personal_topic_preference(uuid,uuid,integer)','EXECUTE') then raise exception 'Old preference writer still available';end if;
 if not has_function_privilege('authenticated','public.set_study_deck_topic_subtree_preference(uuid,uuid,text,integer,text)','EXECUTE')
 or has_function_privilege('anon','public.set_study_deck_topic_subtree_preference(uuid,uuid,text,integer,text)','EXECUTE')
 or has_function_privilege('service_role','public.set_study_deck_topic_subtree_preference(uuid,uuid,text,integer,text)','EXECUTE') then raise exception 'Unexpected subtree RPC audience';end if;
 if exists(select 1 from pg_proc p where pronamespace='public'::regnamespace and proname like 'm117_%' and (has_function_privilege('authenticated',p.oid,'EXECUTE') or has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('service_role',p.oid,'EXECUTE'))) then raise exception 'Private helper exposed';end if;
 if exists(select 1 from pg_roles where rolname='socrates_migrator' and (rolcanlogin or rolsuper or rolbypassrls or rolinherit or rolcreatedb or rolcreaterole)) then raise exception 'Migrator role broadened';end if;
 if (select count(*) from pg_policy where polname like 'm117_%')<>12 then raise exception 'Unexpected policy scope';end if;
 if (select confdeltype from pg_constraint where conname='study_deck_node_preferences_node_library_fkey')<>'r' then raise exception 'Official structural deletion contract changed';end if;
 raise notice 'PASS Migration117: % exact function definitions/owners/grants, preference metadata, restricted writers, RLS and private helper contract',(select count(*) from m117_expected);
end $$;
rollback;
